const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(106.8, -6.2);
  const geometry = point.buffer(50000); // 50km buffer
  const years = [1989, 2004];
  const startDate1 = '1989-01-01';
  const endDate1 = '1989-12-31';
  const startDate2 = '2004-01-01';
  const endDate2 = '2004-12-31';

  // Function to mask clouds and water in Landsat 5 SR
  function maskCloudsAndWater(image) {
    const qa = image.select('pixel_qa');
    const clear = qa.bitwiseAnd(2).neq(0); // bit 1: clear
    const cloudShadow = qa.bitwiseAnd(8).neq(0); // bit 3: cloud shadow
    const cloud = qa.bitwiseAnd(32).neq(0); // bit 5: cloud
    const water = qa.bitwiseAnd(4).neq(0); // bit 2: water
    const mask = clear.and(cloudShadow.eq(0)).and(cloud.eq(0)).and(water.eq(0));
    return image.updateMask(mask);
  }

  // Function to compute NDBI and urban area for a given year
  async function getUrbanArea(startDate, endDate, yearLabel) {
    let collection = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
      .filterDate(startDate, endDate)
      .filterBounds(geometry);

    let size = collection.size().getInfo();
    console.log(`${yearLabel} Images: ${size}`);

    // If no images, try Landsat 4 for 1989 (only for 1989, as 2004 has Landsat 5/7)
    if (size === 0 && yearLabel === '1989') {
      collection = ee.ImageCollection('LANDSAT/LT04/C01/T1_SR')
        .filterDate(startDate, endDate)
        .filterBounds(geometry);
      size = collection.size().getInfo();
      console.log(`${yearLabel} Landsat 4 Images: ${size}`);
    }

    if (size === 0) {
      return { area: null, validPixels: 0, count: size, label: yearLabel };
    }

    // Process images
    const composite = collection
      .map(maskCloudsAndWater)
      .median()
      .clip(geometry);

    // Compute NDBI: (B5 - B4) / (B5 + B4)
    const ndbi = composite.normalizedDifference(['B5', 'B4']).rename('ndbi');

    // Urban mask: NDBI > 0.1
    const urbanMask = ndbi.gt(0.1).rename('urban');

    // Count urban pixels at 30m resolution
    const urbanCount = urbanMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 30,
      maxPixels: 1e9
    }).get('urban');

    const countValue = await urbanCount.getInfo();
    const areaKm2 = countValue * 0.0009; // 30m pixel area = 900 m2 = 0.0009 km2

    // Also count total valid pixels (after masking) for checking C2
    const validMask = composite.select('B3').mask(); // using band 3 as proxy for valid data
    const validCount = validMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 1000, // coarser scale for quick check
      maxPixels: 1e9
    }).get('B3');

    const validValue = await validCount.getInfo();

    return { area: areaKm2, validPixels: validValue, count: size, label: yearLabel };
  }

  // 2. Data Acquisition & Processing
  const area1989 = await getUrbanArea(startDate1, endDate1, '1989');
  const area2004 = await getUrbanArea(startDate2, endDate2, '2004');

  // 3. Check for data issues
  // C1: Empty collection
  if (area1989.count === 0 || area2004.count === 0) {
    console.log(`<answer>C1</answer>`);
    return;
  }

  // C2: No valid pixels after masking
  if (area1989.validPixels === 0 || area2004.validPixels === 0) {
    console.log(`<answer>C2</answer>`);
    return;
  }

  // 4. Validation & Final Answer
  console.log(`1989 Urban Area: ${area1989.area.toFixed(2)} km², Valid Pixels: ${area1989.validPixels}`);
  console.log(`2004 Urban Area: ${area2004.area.toFixed(2)} km², Valid Pixels: ${area2004.validPixels}`);

  // C3: Calculation failure (null/NaN/unrealistic values)
  if (area1989.area === null || area2004.area === null ||
      isNaN(area1989.area) || isNaN(area2004.area) ||
      area1989.area < 0 || area2004.area < 0 ||
      area1989.area > 10000 || area2004.area > 10000) { // Jakarta area < 10,000 km²
    console.log(`<answer>C3</answer>`);
    return;
  }

  // Compare areas
  if (area2004.area > area1989.area) {
    console.log(`<answer>A</answer>`);
  } else {
    console.log(`<answer>B</answer>`);
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
